{"code":"def transform(grid):
    # crop the first (topmost, then leftmost) nonzero connected component
    R=len(grid); C=len(grid[0]) if R else 0
    seen=set(); comps=[]
    for r in range(R):
      for c in range(C):
        if grid[r][c]!=0 and (r,c) not in seen:
          stack=[(r,c)]; seen.add((r,c)); pts=[]
          while stack:
            x,y=stack.pop(); pts.append((x,y))
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
              a,b=x+dx,y+dy
              if 0<=a<R and 0<=b<C and grid[a][b]!=0 and (a,b) not in seen:
                seen.add((a,b)); stack.append((a,b))
          comps.append(pts)
    if not comps:return []
    pts=min(comps,key=lambda p:min(p))
    r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    return [row[c0:c1+1] for row in grid[r0:r1+1]]"}

